-- Fictional 2017-2026 history, generated offline by scripts/generate_demo_history.py.
-- Public issue terms are genuine; inflation, accrued interest, trades and quotes are MODEL DATA.
-- Do not edit an applied Flyway migration. Local edits use the UI/SQL, then export_demo.py.
DO $demo_history$
BEGIN
  IF current_database() <> 'my-funds-demo' AND current_database() NOT LIKE 'my-funds-demo-test%' THEN
    RAISE EXCEPTION 'This seed is restricted to the isolated my-funds-demo database';
  END IF;
  IF (SELECT COUNT(*) FROM mf_transaction) <> 13
     OR (SELECT SUM(mf_transaction.purchasecost) FROM mf_transaction) <> 331400
     OR (SELECT COUNT(*) FROM mf_bond_position) <> 2
     OR (SELECT SUM(mf_bond_position.purchase_cost) FROM mf_bond_position) <> 140000
     OR EXISTS (
       SELECT mf_transaction.wallet_id, mf_transaction.stock_id, mf_transaction.amount,
              mf_transaction.purchasecost, mf_transaction.purchasedate, mf_transaction.transactiontype
       FROM mf_transaction
       EXCEPT SELECT * FROM (VALUES
         (2,1,250,78000,'2024-01-15'::date,'BUY'),(2,1,125,44000,'2025-04-15'::date,'BUY'),
         (2,2,300,47000,'2024-02-15'::date,'BUY'),(2,3,200,41000,'2024-03-15'::date,'BUY'),
         (2,4,50,18000,'2025-02-15'::date,'BUY'),(2,5,50,11000,'2025-03-15'::date,'BUY'),
         (2,6,50,8500,'2025-05-15'::date,'BUY'),(3,7,1200,26000,'2024-06-15'::date,'BUY'),
         (3,7,200,5000,'2025-06-15'::date,'SELL'),(3,8,400,14000,'2024-08-15'::date,'BUY'),
         (3,9,50,14500,'2025-01-15'::date,'BUY'),(3,10,10,8400,'2025-02-15'::date,'BUY'),
         (3,11,0.05,16000,'2025-03-15'::date,'BUY')) AS original_transactions
     )
     OR EXISTS (
       SELECT mf_bond_position.bond_issue_id, mf_bond_position.available_units,
              mf_bond_position.blocked_units, mf_bond_position.purchase_date, mf_bond_position.maturity_date
       FROM mf_bond_position
       EXCEPT SELECT * FROM (VALUES
         (1,1000,0,'2024-01-01'::date,'2034-01-01'::date),
         (2,400,0,'2025-01-01'::date,'2035-01-01'::date)) AS original_bonds
     ) THEN
    RAISE EXCEPTION 'Preserving modified demo data: review the history migration before applying it';
  END IF;

CREATE TABLE mf_demo_dataset_identity (
  id integer PRIMARY KEY CHECK (id = 1),
  dataset_key text NOT NULL CHECK (dataset_key = 'my-funds-fictional-demo'),
  synthetic boolean NOT NULL CHECK (synthetic),
  as_of_date date NOT NULL
);
DELETE FROM mf_transaction;
DELETE FROM mf_stock_quote;
DELETE FROM mf_currency_rate;
DELETE FROM mf_bond_interest_value;
DELETE FROM mf_bond_position;
DELETE FROM mf_bond_issue;
UPDATE mf_stock SET currency_id = 4 WHERE id = 2;
CREATE TEMP TABLE demo_interest_period (bond_issue_id integer, start_date date, end_date date, opening_balance numeric, rate numeric, period_number integer) ON COMMIT DROP;
SELECT demo_interest_period.bond_issue_id, demo_dates.valuation_date::date,
       ROUND(demo_interest_period.opening_balance * (1 + demo_interest_period.rate / 100 *
         (demo_dates.valuation_date::date - demo_interest_period.start_date)::numeric /
         (demo_interest_period.end_date - demo_interest_period.start_date)) - 100, 12),
       demo_interest_period.period_number, '2026-11-13'::timestamp
FROM demo_interest_period
CROSS JOIN LATERAL generate_series(demo_interest_period.start_date,
  LEAST(demo_interest_period.end_date - 1, '2026-11-13'::date), INTERVAL '1 day') AS demo_dates(valuation_date);
-- Reconcile sub-grosz numerical precision, not an economic last-day jump.
UPDATE mf_bond_interest_value SET accrued_interest = accrued_interest +
  (150000 - (SELECT SUM(mf_bond_position.available_units * (100 + mf_bond_interest_value.accrued_interest))
   FROM mf_bond_position JOIN mf_bond_issue ON mf_bond_issue.id = mf_bond_position.bond_issue_id
   JOIN mf_bond_interest_value ON mf_bond_interest_value.bond_issue_id = mf_bond_issue.id
     AND mf_bond_interest_value.base_valuation_date = '2026-11-13'::date - (mf_bond_position.purchase_date - mf_bond_issue.sale_start_date))) /
  (SELECT mf_bond_position.available_units FROM mf_bond_position WHERE mf_bond_position.bond_issue_id = 1)
WHERE mf_bond_interest_value.bond_issue_id = 1 AND mf_bond_interest_value.base_valuation_date =
  '2026-11-13'::date - (SELECT mf_bond_position.purchase_date - mf_bond_issue.sale_start_date
  FROM mf_bond_position JOIN mf_bond_issue ON mf_bond_issue.id = mf_bond_position.bond_issue_id WHERE mf_bond_issue.id = 1);
PERFORM setval(pg_get_serial_sequence('mf_bond_issue', 'id'), (SELECT MAX(mf_bond_issue.id) FROM mf_bond_issue));
END;
$demo_history$;
